    // ── SESSION ──
    private string? _maTruongBo;
    private string? _selectedNamHoc;
    private string? _selectedCapHoc;

    // ── FILTER ──
    private List<KhoiHoc_DTO>  _khoiList    = new();
    private List<LopHoc_DTO>   _allLopList  = new();
    private List<LopHoc_DTO>   _lopFiltered = new();
    private int    _selKhoiId  = 0;
    private string _selMaLop   = "";
    private string _selTenLop  = "";
    private int    _selLopId   = 0;

    // ── TAB ──
    // "dacdiem" | "kehoach" | "congtac"
    private string _activeTab = "dacdiem";

    // ── DATA MODEL ──
    private ScnKeHoachChuNhiemDTO _model = new();

    // ── QUILL STATE ──
    // Index: 0 = dacdiem, 1 = kehoach, 2 = congtac
    private bool[] _quillInit   = { false, false, false };
    private bool[] _isSaving    = { false, false, false };

    // ── LOADING ──
    private bool _isLoading = false;

    // ── TOAST ──
    private string _toastMsg  = "";
    private string _toastCss  = "";
    private string _toastIcon = "";
    private System.Threading.CancellationTokenSource? _toastCts;

    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

        var taskKhoi = TruongService.hGetDanhSachKhoi(_maTruongBo ?? "", _selectedCapHoc ?? "1");
        var taskLop  = TruongService.hGetDanhSachLop(_maTruongBo ?? "", _selectedCapHoc ?? "1", _selectedNamHoc ?? "");

        await Task.WhenAll(taskKhoi, taskLop);

        _khoiList   = taskKhoi.Result;
        _allLopList = taskLop.Result;

        if (_khoiList.Any())
        {
            _selKhoiId   = _khoiList[0].MaKhoi;
            _lopFiltered = _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        }
        else _lopFiltered = _allLopList.ToList();

        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
            await LoadData();
        }
    }

    // ── AFTER RENDER → Init Quill khi tab hiển thị ──
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (string.IsNullOrEmpty(_selMaLop) || _isLoading) return;

        // Mỗi tab chỉ init Quill 1 lần sau khi element đã mount
        int tabIdx = _activeTab switch
        {
            "dacdiem" => 0,
            "kehoach" => 1,
            "congtac" => 2,
            _         => -1
        };

        if (tabIdx < 0 || _quillInit[tabIdx]) return;

        _quillInit[tabIdx] = true;

        var (editorId, instanceKey, placeholder, content) = tabIdx switch
        {
            0 => ("khcn-editor-dacdiem", "dacdiem",
                  "Nhập đặc điểm tình hình lớp học...",
                  _model.DacDiemTinhHinh ?? ""),
            1 => ("khcn-editor-kehoach", "kehoach",
                  "Nhập các nội dung kế hoạch chủ nhiệm...",
                  _model.NdKeHoachChuNhiem ?? ""),
            _ => ("khcn-editor-congtac", "congtac",
                  "Nhập nội dung công tác chủ nhiệm...",
                  _model.NdCongTacChuNhiem ?? "")
        };

        try
        {
            await JS.InvokeVoidAsync("scnKhcn.init", editorId, instanceKey, placeholder, content);
        }
        catch { /* JS chưa load hoặc element chưa mount */ }
    }

    // ── FILTER EVENTS ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        _selKhoiId   = int.TryParse(e.Value?.ToString(), out var kv) ? kv : 0;
        _lopFiltered = _selKhoiId == 0
            ? _allLopList.ToList()
            : _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();

        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
        }
        else { _selMaLop = ""; _selTenLop = ""; _selLopId = 0; }

        await ResetQuillAsync();
        if (!string.IsNullOrEmpty(_selMaLop))
            await LoadData();
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        _selMaLop = e.Value?.ToString() ?? "";
        var lop   = _lopFiltered.FirstOrDefault(l => l.MaLopBo == _selMaLop);
        _selTenLop = lop?.TenLop ?? "";
        _selLopId  = lop?.IdLopBo ?? 0;
        await ResetQuillAsync();
        if (!string.IsNullOrEmpty(_selMaLop))
            await LoadData();
    }

    private void SetTab(string tab)
    {
        if (_activeTab == tab) return;
        _activeTab = tab;
        // Reset trạng thái init của tab mới để Quill khởi tạo lại khi cần
        int idx = tab switch { "dacdiem" => 0, "kehoach" => 1, "congtac" => 2, _ => -1 };
        if (idx >= 0) _quillInit[idx] = false;
        StateHasChanged();
    }

    // ── LOAD DATA ──
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(_selMaLop)) return;
        _isLoading = true; StateHasChanged();
        try
        {
            var list = await TruongService.hGetKeHoachChuNhiem(
                lopId: _selLopId > 0 ? _selLopId : (int?)null,
                namHoc: _selectedNamHoc ?? "");

            _model = list.FirstOrDefault() ?? new ScnKeHoachChuNhiemDTO
            {
                Id               = 0,
                KhoiId           = _selKhoiId > 0 ? _selKhoiId : (int?)null,
                LopId            = _selLopId  > 0 ? _selLopId  : (int?)null,
                NamHoc           = _selectedNamHoc ?? "",
                DacDiemTinhHinh  = "",
                NdKeHoachChuNhiem = "",
                NdCongTacChuNhiem = ""
            };
            // Reset Quill để nạp nội dung mới (đã await ở trên, không cần reset lại)
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error");
        }
        finally
        {
            _isLoading = false;
            // Đảm bảo tab active sẽ init lại Quill với nội dung mới
            int idx = _activeTab switch { "dacdiem" => 0, "kehoach" => 1, "congtac" => 2, _ => -1 };
            if (idx >= 0) _quillInit[idx] = false;
            StateHasChanged();
        }
    }

    // Xóa hoàn toàn Quill instances + DOM cũ trước khi load lớp mới
    private async Task ResetQuillAsync()
    {
        _quillInit[0] = false;
        _quillInit[1] = false;
        _quillInit[2] = false;
        try
        {
            // destroyAllWithDom xóa cả DOM (toolbar + container) mà Quill đã tạo
            await JS.InvokeVoidAsync("scnKhcn.destroyAllWithDom",
                new[] { "khcn-editor-dacdiem", "khcn-editor-kehoach", "khcn-editor-congtac" });
        }
        catch { /* JS chưa sẵn sàng hoặc element không tồn tại */ }
    }

    // ── LƯU TỪNG TAB ──
    private async Task SaveTab(string tab)
    {
        int idx = tab switch { "dacdiem" => 0, "kehoach" => 1, "congtac" => 2, _ => -1 };
        if (idx < 0 || _isSaving[idx]) return;

        _isSaving[idx] = true; StateHasChanged();
        try
        {
            // Lấy HTML từ Quill theo key
            string html = await JS.InvokeAsync<string>("scnKhcn.getContent", tab);

            _model ??= new ScnKeHoachChuNhiemDTO();
            _model.NamHoc  = _selectedNamHoc ?? "";
            _model.KhoiId  = _selKhoiId > 0 ? _selKhoiId : (int?)null;
            _model.LopId   = _selLopId  > 0 ? _selLopId  : (int?)null;

            switch (tab)
            {
                case "dacdiem": _model.DacDiemTinhHinh  = html; break;
                case "kehoach": _model.NdKeHoachChuNhiem = html; break;
                case "congtac": _model.NdCongTacChuNhiem = html; break;
            }

            await TruongService.hUpsertKeHoachChuNhiem(_model);

            // Nếu là INSERT mới, reload để lấy Id
            if (_model.Id <= 0)
            {
                var list = await TruongService.hGetKeHoachChuNhiem(
                    lopId: _selLopId > 0 ? _selLopId : (int?)null,
                    namHoc: _selectedNamHoc ?? "");
                _model = list.FirstOrDefault() ?? _model;
            }

            var tabLabel = tab switch
            {
                "dacdiem" => "Đặc điểm tình hình",
                "kehoach" => "Kế hoạch chủ nhiệm",
                "congtac" => "Công tác chủ nhiệm",
                _         => "Nội dung"
            };
            await ShowToast($"Đã lưu {tabLabel}!", "toast-ok", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error");
        }
        finally { _isSaving[idx] = false; StateHasChanged(); }
    }

    // ── TOAST ──
    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts  = new System.Threading.CancellationTokenSource();
        _toastMsg  = msg; _toastCss = css; _toastIcon = icon;
        StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastMsg = ""; StateHasChanged(); }
        catch (TaskCanceledException) { }
    }

